import * as L from './m13-layout.js';
import {createM13Art} from './m13-art.js?v=4.3';
const $=id=>document.getElementById(id),q=new URLSearchParams(location.search),mobile=/iPhone|iPad|Android/.test(navigator.userAgent),gpu=q.get('gpu')==='1'||(!mobile&&q.get('gpu')!=='0'&&!!navigator.gpu);
const timeout=(p,ms)=>Promise.race([p,new Promise((_,r)=>setTimeout(()=>r(Error('Délai graphique dépassé')),ms))]);let T,renderer,canvas=$('world');const status=s=>$('status').textContent=s;
async function init(){if(gpu){try{status('Initialisation WebGPU…');T=await timeout(import('./vendor/three.webgpu.min.js'),10000);renderer=new T.WebGPURenderer({canvas,antialias:!mobile});await timeout(renderer.init(),7000);return;}catch(e){try{renderer?.dispose()}catch{}const c=canvas.cloneNode();canvas.replaceWith(c);canvas=c;}}
status('Initialisation WebGL 2…');T=await timeout(import('./vendor/three.module.min.js'),10000);renderer=new T.WebGLRenderer({canvas,antialias:!mobile,preserveDrawingBuffer:true});}
try{await init();renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;renderer.setPixelRatio(Math.min(devicePixelRatio,mobile?1:1.6));renderer.setSize(innerWidth,innerHeight,false);
const scene=new T.Scene(),camera=new T.PerspectiveCamera(65,innerWidth/innerHeight,.08,1400);
status('Construction de la géométrie réelle M13…');const art=createM13Art(T,scene,{quality:mobile?'normal':'high',mobile,webgpu:!!renderer.backend?.isWebGPUBackend});await timeout(art.ready,12000);if(art.stats().revision!=='m13-art-v4.3')throw Error('Version du décor incorrecte : V4.3 requise');
const cg=new T.Group(),ng=new T.Group(),g=new T.BoxGeometry(1,1,1),cm=new T.MeshBasicMaterial({color:0xff4488,wireframe:true,depthTest:false}),nm=new T.MeshBasicMaterial({color:0x39ff99,transparent:true,opacity:.22,depthWrite:false,side:T.DoubleSide});for(const c of L.buildCollisions()){const o=new T.Mesh(g,cm);o.scale.set(c.hx*2,c.height,c.hz*2);o.position.set(c.x,c.y+c.height/2,c.z);cg.add(o)}for(const d of [...L.DECKS,...L.ANNEXES]){const o=new T.Mesh(new T.PlaneGeometry(d.w,d.d),nm);o.rotation.x=-Math.PI/2;o.position.set(d.x,d.height+.05,d.z);ng.add(o)}cg.visible=ng.visible=false;scene.add(cg,ng);
let yaw=0,pitch=0,orbit=false,angle=0,last=0,frames=0,elapsed=0,fps=0;const keys=new Set(),move=[0,0],look=[0,0],up={on:false},down={on:false};function pose(x,y,z,tx,ty,tz){orbit=false;camera.position.set(x,y,z);camera.lookAt(tx,ty,tz);camera.rotation.reorder('YXZ');yaw=camera.rotation.y;pitch=camera.rotation.x}function overview(){pose(40,155,220,0,8,-20)}overview();
const bind=(id,v)=>{const e=$(id),k=e.firstElementChild;let pointer=null;function set(p){const b=e.getBoundingClientRect(),x=(p.clientX-b.left-b.width/2)/(b.width/2),y=(p.clientY-b.top-b.height/2)/(b.height/2),n=Math.max(1,Math.hypot(x,y));v[0]=x/n;v[1]=y/n;k.style.transform='translate('+v[0]*32+'px,'+v[1]*32+'px)'}e.onpointerdown=p=>{pointer=p.pointerId;e.setPointerCapture(pointer);set(p)};e.onpointermove=p=>{if(p.pointerId===pointer)set(p)};e.onpointerup=e.onpointercancel=e.onlostpointercapture=()=>{pointer=null;v[0]=v[1]=0;k.style.transform=''}};bind('move',move);bind('look',look);
for(const [id,v] of [['up',up],['down',down]]){$(id).onpointerdown=e=>{$(id).setPointerCapture(e.pointerId);v.on=true};$(id).onpointerup=$(id).onpointercancel=$(id).onlostpointercapture=()=>v.on=false}
let drag=null;canvas.onpointerdown=e=>{if(e.pointerType==='mouse'){drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)}};canvas.onpointermove=e=>{if(drag){yaw-=(e.clientX-drag[0])*.004;pitch-=(e.clientY-drag[1])*.004;drag=[e.clientX,e.clientY]}};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
window.onkeydown=e=>{if(e.target.tagName==='INPUT'||e.target.tagName==='SELECT')return;keys.add(e.code);if(e.code==='KeyH')document.body.classList.toggle('clean');if(e.code==='KeyT')$('topview').click();if(e.code==='KeyP')$('capture').click();if(['Space','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault()};window.onkeyup=e=>keys.delete(e.code);window.onblur=()=>{keys.clear();up.on=down.on=false};canvas.ondblclick=()=>document.body.classList.remove('clean');canvas.onwheel=e=>{$('speed').value=Number($('speed').value)-Math.sign(e.deltaY)*2};
for(const [i,p] of L.INTERACTIONS.entries()){const o=document.createElement('option');o.value=i;o.textContent=(i+1)+' · '+p.label;$('sector').append(o)}$('sector').onchange=()=>{const p=L.INTERACTIONS[+$('sector').value];pose(p.x,p.y+2.6,p.z+2.8,p.x,p.y+1.7,p.z-6)};$('overview').onclick=overview;$('topview').onclick=()=>pose(0,230,-10,0,0,-10.01);$('orbit').onclick=()=>orbit=!orbit;$('colliders').onclick=()=>cg.visible=!cg.visible;$('nav').onclick=()=>ng.visible=!ng.visible;$('clean').onclick=()=>document.body.classList.toggle('clean');$('backend').textContent=gpu&&renderer.backend?.isWebGPUBackend?'Passer WebGL':'Essayer WebGPU';$('backend').onclick=()=>location.search=gpu?'?gpu=0':'?gpu=1';
let capture=false;$('capture').onclick=()=>capture=true;window.onresize=()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight,false)};
const key=(...ks)=>ks.some(k=>keys.has(k))?1:0;let busy=false;
async function frame(t){requestAnimationFrame(frame);if(busy)return;busy=true;try{const dt=Math.min(.05,last?(t-last)/1000:1/60);last=t;const v=+$('speed').value*(key('ShiftLeft','ShiftRight')?3:1);if(orbit){angle+=dt*.17;pose(Math.sin(angle)*235,130,Math.cos(angle)*235,0,8,-15);orbit=true}else{yaw-=look[0]*dt*1.8;pitch-=look[1]*dt*1.6;pitch=Math.max(-1.56,Math.min(1.56,pitch));const x=move[0]+key('KeyD')-key('KeyA','KeyQ'),z=-move[1]+key('KeyW','KeyZ')-key('KeyS');camera.position.x+=(Math.cos(yaw)*x-Math.sin(yaw)*z)*v*dt;camera.position.z+=(-Math.sin(yaw)*x-Math.cos(yaw)*z)*v*dt;camera.position.y+=(Number(up.on)-Number(down.on)+key('Space')-key('ControlLeft','ControlRight'))*v*dt;camera.rotation.set(pitch,yaw,0,'YXZ')}
art.update(t/1000,dt,camera,{x:camera.position.x,z:camera.position.z,elevation:camera.position.y});if(renderer.renderAsync)await renderer.renderAsync(scene,camera);else renderer.render(scene,camera);if(capture){capture=false;const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='M13-capture.png';a.click()}frames++;elapsed+=dt;if(elapsed>.5){fps=Math.round(frames/elapsed);frames=elapsed=0;$('telemetry').textContent=fps+' FPS | '+camera.position.x.toFixed(0)+', '+camera.position.y.toFixed(0)+', '+camera.position.z.toFixed(0)+' m | '+(renderer.info.render.calls??renderer.info.render.drawCalls??'—')+' appels'}}catch(e){status('Erreur de rendu : '+e.message);$('load').hidden=false}finally{busy=false}}
if(renderer.renderAsync)await timeout(renderer.renderAsync(scene,camera),12000);else renderer.render(scene,camera);$('load').hidden=true;requestAnimationFrame(frame);
}catch(e){status('Impossible de lancer : '+e.message);$('load').hidden=false}
